class Solution:
    def splitLoad(self, loads: list[int], groups: int) -> int:
        lower, upper = max(loads), sum(loads)
        while lower < upper:
            bound = (lower + upper) // 2
            used, running = 1, 0
            for load in loads:
                if running + load > bound:
                    used += 1
                    running = 0
                running += load
            if used <= groups:
                upper = bound
            else:
                lower = bound + 1
        return lower

class Solution  {
    public int splitLoad(int[] loads,int groups)  {
        int lo=Arrays.stream(loads).max().orElse(0),hi=Arrays.stream(loads).sum();
        while(lo<hi) {
            int mid=lo+(hi-lo)/2,used=1,total=0;
            for(int load:loads) {
                if(total+load>mid) {
                    used++;
                    total=0;
                }
                total+=load;
            }
            if(used<=groups)hi=mid;
            else lo=mid+1;
        }
        return lo;
    }
}

class Solution  {
    splitLoad(loads:number[],groups:number):number {
        let lo=Math.max(...loads),hi=loads.reduce((a,b)=>a+b,0);
        while(lo<hi) {
            const mid=Math.floor((lo+hi)/2);
            let used=1,total=0;
            for(const load of loads) {
                if(total+load>mid) {
                    used++;
                    total=0;
                }
                total+=load;
            }
            if(used<=groups)hi=mid;
            else lo=mid+1;
        }
        return lo;
    }
}
